#include <iostream>
#include <cmath>

long long findTheNumberOfLinesForLady(long long forTheNumberOfSquares) {
    double a = std::sqrt(static_cast<double>(forTheNumberOfSquares));
    long long b = static_cast<long long>(a);

    if (b * b == forTheNumberOfSquares) return 2 * b;
    if (b * (b + 1) >= forTheNumberOfSquares) return 2 * b + 1;
    return 2 * b + 2;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long numberOfSquares;
    if (std::cin >> numberOfSquares) {
        std::cout << findTheNumberOfLinesForLady(numberOfSquares) << std::endl;
    }
    return 0;
}

